#include "coordinator.h"
#include "actions.h"
#include <cstdio>
#include <memory>
#include <stdexcept>
using namespace tactics;
static void require(bool value,const char* why){if(!value){std::printf("NATIVE_FARM_READY_FAIL %s\n",why);std::fflush(stdout);throw std::runtime_error(why);}}
int main(){Geometry geo;Memory memory;std::unique_ptr<World> world;int gi=-1,phase=0,waits=0;bool evaluated=false,staged=false;
 while(true){if(bc::is_draft()){const auto old=bc::draft::current_draft(bc::team::ally);for(auto pick:{bc::champion_draft::cassi_and_issac,bc::champion_draft::varg,bc::champion_draft::ryth,bc::champion_draft::vendetta,bc::champion_draft::tavi})if(std::find(old.begin(),old.end(),pick)==old.end()){bc::draft::pick(pick);break;}}
 else if(phase<4){if(!geo.initialized){geo.initialize();bc::end_turn();continue;}if(gi<0){int best=unreachable;for(unsigned i=0;i<geo.groups.size();++i){const auto&g=geo.groups[i];if(g.gems>0&&g.spawns.size()>1&&g.initial_strength>0&&!g.monolith){int d=geo.at(geo.home,g.spawns[0].pos);if(d<best){best=d;gi=i;}}}require(gi>=0,"native public map has damaging multi-member group");}
 const Pos target=geo.groups[gi].spawns.front().pos;if(!geo.goal_field(target,0)||bc::fuel_remaining()<60000){bc::end_turn();continue;}if(!world)world=std::make_unique<World>(geo,memory);auto&w=*world;w.refresh();if(w.self.type!=4){phase=4;bc::end_turn();continue;}
 if(phase==0){if(w.groups[gi].fresh(w.round)&&distance(w.self.pos,target)<=5){phase=1;}else if(auto step=w.toward(target,5)){if(potential_camp_pressure(*step,geo.groups,w.groups,w.round)){std::printf("NATIVE_FARM_READY_SCRIPT_BLOCKED %d %d\n",w.self.id,w.round);phase=4;}else{Action a=moving(*step,"fixture-safe-observation");require(execute(w,a).success,"actual observation walk accepted");}}}
 else if(phase==1){const auto crew=helpers_for(w,gi,target);require(!crew.empty()&&!crew.front().ready&&crew.front().dps==0,"actual observed out-of-range owner has zero ready damage");const auto quote=evaluate_farm(w,gi);require(quote.observation_only&&!quote.ready&&!quote.prospective_feasible&&quote.rate==0&&quote.clear_time==unreachable,"native multicamp outside-range quote is observation, never finite free-pressure clear");evaluated=true;memory.mission={};memory.mission.phase=Phase::Assemble;memory.mission.group=gi;memory.mission.target=target;memory.mission.start=memory.mission.last_progress=w.round;memory.mission.expiry=w.round+20;phase=2;std::printf("NATIVE_FARM_READY_QUOTE %d %d %d %d %d %d %d\n",w.self.id,w.round,gi,int(w.self.strength),w.self.range,w.self.pos.x,w.self.pos.y);}
 else if(phase==2){const double hp=w.self.hp;auto proposal=farming(w,memory);if(proposal){require(proposal->action.kind==Kind::None||proposal->action.kind==Kind::Move,"unnamed unready assembly cannot attack or cast");require(proposal->mission.rate==0&&proposal->value==0,"inspection never publishes earned gem income");if(proposal->action.kind==Kind::Move){require(!potential_camp_pressure(proposal->action.at,geo.groups,w.groups,w.round),"actual unnamed staging target stays outside every monster potential range");require(execute(w,proposal->action).success,"actual staging walk accepted");staged=true;}memory.mission=proposal->mission;}require(w.self.hp==hp,"probe does not spend health on unknown clear");++waits;if(waits>=7){require(evaluated,"actual zero-DPS quote was exercised");require(memory.failed_group==gi,"unfunded unnamed assembly releases after bounded wait");std::printf("NATIVE_FARM_READY_PASS %d %d %d %d\n",w.self.id,w.round,waits,int(staged));phase=4;}}
 }
 bc::end_turn();}
}
